  'settings.reconnect.upnpState': 'Ништа више није потребно. Мрежни пролаз се нађе питањем мреже, и управо то од овога прави начин који ради без иједног податка о рутеру.',
  'settings.reconnect.upnpLocation': 'URL описа мрежног пролаза',
