  'settings.reconnect.script': 'Скрипта',
  'settings.reconnect.scriptHint': 'Уписује се у приватну привремену датотеку, а тумач добија њену путању, па ништа одавде никада не заврши под наводницима у командној линији. Променљиве се умећу пре него што се датотека упише, што значи да лозинка укуцана у ово поље стигне и у ту датотеку: уз %%password%% остаје у пољу за лозинку.',

  'settings.reconnect.router': 'Адреса рутера',
