  'settings.reconnect.importFailed': 'Скрипту није било могуће прочитати: {reason}',

  'settings.reconnect.checkTitle': 'Провера адресе',
  'settings.reconnect.checkUrl': 'URL за проверу IP-а',
  'settings.reconnect.checkUrlHint': 'Дохвата се пре него што се начин изведе и још једном после тога; извршавање се рачуна као готово чим се адреса коју исписује промени. Подразумеване вредности намерно нема: управљач преузимања који сам држиш не би требало да почне да јавља твоју адресу услузи коју никада ниси изабрао. Оно што исписује мора бити адреса коју види интернет, јер страница која враћа адресу из твоје сопствене мреже не разликује поновно повезивање од ничега.',
  'settings.reconnect.checkPresets': 'Познате услуге',
  'settings.reconnect.checkPresetsHint': 'Пречица за онога ко нема свој избор, а не подразумевана вредност: ниједна се не бира уместо тебе, и свака страница која испише твоју јавну адресу обавља посао једнако добро.',
  'settings.reconnect.interval': 'Секунди између провера (1 до 60)',
  'settings.reconnect.intervalHint': 'Колико чекати између два погледа на URL провере пошто се начин извршио. Доња граница постоји јер петља без ње претвара услугу провере у мету.',
  'settings.reconnect.timeout': 'Секунди проверавања (5 до 900)',
  'settings.reconnect.timeoutHint': 'Колико још гледати пре него што се извршавање прогласи неуспелим. Поновно повезивање које четврт сата касније и даље чека пропало је, шта год овде писало. Временско ограничење мање од размака подиже се на њега, иначе би извршавање било готово пре него што се догодила и једна провера.',
