  'settings.reconnect.policy': 'Када се то деси само',
  'settings.reconnect.policyHint': 'Аутоматска поновна повезивања окидају се на једном месту, а ова страница то место није. Једно креће када сама позадина преузимања после паузе затражи још један покушај, јер тако хостер каже да је ограничење везано за ову адресу. Никада не ради док је ред заустављен, јер поновно покретање рутера обара преузимања која још трају. Никада не ради док поновно повезивање није у потпуности подешено. Одједном ради само једно: други захтев чека пресуду првог уместо да се с њим отима око рутера. А ако се адреса не помери, ништа се не убрзава и уобичајена пауза између покушаја одради своје.',

