  'strip.label': 'Збирови преузимања',
  'strip.of': 'од',
  'strip.hint': 'Добијени бајтови наспрам дугованих. Завршене, неуспеле и тек покупљене везе остају ван збира, као и све чију величину хостер још није рекао - нагађање би ту било број са којим нико ништа не може.',
