  'quick.title': 'Брза подешавања',
  'quick.chunksHint': 'Везе које отвара једно преузимање. Ово није број веза отворених управо сада: бекенд јавља своју брзину и своје бајтове, никада колико утичница држи, па таквог броја нема ни да се прикаже. Уз 0 избор се враћа апликацији.',

