  'settings.access.ownRelay.save': 'Сачувај',
  'settings.access.ownRelay.everyInstance': 'Ова адреса важи само за ову инстанцу. Упиши је на свакој.',
  'settings.access.ownRelay.containerLabel': 'Као сопствени контејнер',
  'settings.access.ownRelay.containerHint': 'Ако ниједна твоја инстанца није доступна споља, релеј мора да стоји другде: на твом серверу или малом VPS-у. Инсталирај контејнер из Unraid Community Applications или наредбом испод.\n\nКонтејнеру не треба подешавање: покрени га, упиши његову адресу изнад, готово. Ништа не чува, па нема шта ни да се резервно копира.',
