  'settings.access.identity.title': 'Идентитет ове инстанце',
  'settings.access.identity.nameLabel': 'Назив',
  'settings.access.identity.namePlaceholder': 'нпр. Кућни сервер',
  'settings.access.identity.nameHint': 'Понуђено прво при упаривању и у QR коду испод, уместо онога како овај рачунар случајно назива оперативни систем или контејнерско извршно окружење. Опционо - оставите празно да бисте наставили да користите тај назив.',
  'settings.access.identity.domainsLabel': 'Познати домени',
  'settings.access.identity.domainsHint': 'Аутоматски се запамти чим кроз њега стварно стигне захтев, тако да остаје овде наведен чак и када каснији захтеви уместо тога стижу преко LAN IP адресе. Додајте један ручно за домен који је већ подешен, али још није посећен - једна потпуна адреса по реду, нпр. https://kl.example.com.',
  'settings.access.cardTitle': 'Повезивање инстанци и удаљени приступ',
  'settings.access.phrase.body': 'Једна фраза повезује све ваше KnightLoader инстанце. Направите је овде и налепите у остале инстанце - без налога, без пријаве, без ичега за подешавање.',
  'settings.access.phrase.noPasswordWarning': 'Ова инстанца нема лозинку. Фраза отвара сваку инстанцу коју њоме повежете, па ко је овде прочита стиже до свих, не само до ове. Боље прво поставите лозинку изнад.',
  'settings.access.phrase.activate': 'Направи фразу',
  'settings.access.phrase.howLead': 'Дванаест речи и то је све. Ево како и шта се притом дешава:',
  'settings.access.phrase.howStep1': 'На овој инстанци притисни „{button}“. Појавиће се дванаест речи.',
  'settings.access.phrase.howStep2': 'Отвори KnightLoader на другом уређају, дођи на ову исту страницу, притисни „{button}“ и упиши дванаест речи.',
  'settings.access.phrase.howStep3': 'Готово! Свака инстанца се сада појављује код друге под „Инстанце“ и можеш управљати било којом са било које. Са укљученим релејом твоје инстанце су доступне и изван твоје мреже.',
  'settings.access.phrase.howWhat': 'Речи су тајна, а не адреса. Свака инстанца из њих израчуна два кључа: један за проналажење осталих, један за шифровање.\n\nДа би се нашле, свака инстанца сама зове исто место сусрета на интернету. Ко покаже исти кључ, буде спојен. Зато ниједна твоја инстанца не мора бити доступна споља.\n\nМесто сусрета не може да чита. Твоје речи никада не види, а све што кроз њега пролази шифровано је другим кључем.',
  'settings.access.phrase.statusDisconnected': 'Није повезано',
  'settings.access.phrase.statusHintProject': 'Повезано с релејом пројекта. Удаљени приступ је подешен.',
  'settings.access.phrase.statusHintOwn': 'Повезано са сопственим релејом. Удаљени приступ је подешен.',
  'settings.access.phrase.statusHintOff': 'Ниједан релеј није активан. Твоје инстанце су доступне само у локалној мрежи.',
  'settings.access.phrase.statusHintLost': 'Нема везе с релејом. KnightLoader и даље покушава. До тада се инстанце налазе само у локалној мрежи.',
  'settings.access.phrase.statusConnected': 'Повезано',
