  'settings.nav.browsertools': 'Прегледач и апликација',
  'settings.browsertools.bookmarkletStep1': 'Превуци дугме испод на траку са обележивачима твог прегледача - чува се као свако друго обележивач, ништа се не инсталира.',
  'settings.browsertools.bookmarkletStep2': 'На било којој страници кликни на њега (прво избери текст ако желиш само њега). Отвара се мали KnightLoader картица са везом те странице или изабраним текстом, већ попуњена - прегледај је и додај је одатле као преузимање.',
