  'settings.resolvers.moduleUnavailableHint': 'Све испод свеједно се чува и ступа на снагу чим yt-dlp постане доступан - уређивањем већ сада ништа се не губи.',
  'settings.resolvers.intro': 'Подешавања за yt-dlp позадину, која преузима медијске и стриминг сајтове које yt-dlp сам подржава. Која услуга уопште обрађује дату везу - yt-dlp, debrid налог, headless JD sidecar - одлучује се редоследом рутирања на страници Налози; овде је описано само оно што yt-dlp ради пошто је веза већ усмерена ка њему.',
  'settings.resolvers.quality': 'Квалитет',
