  'settings.torrents.portMapHint': 'Тражи од рутера да преко UPnP-а проследи горњи порт на овај рачунар, како би га пирови иза другог рутера ипак могли достићи. Не подржавају сви рутери ово, а неки прихватају захтев иако то заправо не ради.',
  'settings.torrents.portMapButton': 'Покушај UPnP мапирања',
