  'settings.torrents.portMapUnconfirmed': 'Рутер је прихватио захтев, али није било могуће потврдити да мапирање заиста ради. Неки рутери то раде тихо - покушајте проверу повезивости изван мреже.',
  'settings.torrents.portMapFailed': 'Порт није било могуће мапирати: {error}',
  'settings.torrents.portMapUnavailable': 'Ова верзија још увек не нуди мапирање порта.',
  'settings.torrents.networkTitle': 'Откривање пирова',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Проналази пирове без икаквог трекера, користећи друге BitTorrent клијенте као дистрибуирани именик.',
  'settings.torrents.pex': 'Размена пирова (PEX)',
  'settings.torrents.pexHint': 'Размењује познате пирове са већ повезанима, како би се рој са мало пирова брже пронашао.',
  'settings.torrents.privateNote': 'Приватни торент аутоматски искључи оба чим су познати његови метаподаци, без обзира на подешавање овде - одмах код отпремљене .torrent датотеке, или чим сопствени метаподаци magnet везе стигну из роја. Већина приватних трекера банује налоге који користе било шта од тога.',
  'settings.torrents.engineNote': 'Циљни однос сидовања, циљно трајање сидовања и порт сада заиста утичу на сваки торент који покрене овај механизам - порт ипак само за баш први торент од последњег поновног покретања ове инстанце, јер се сопствени торент клијент механизма гради само једном и никада се више поново не гради; касније чување ипак се исправно чува и ступа на снагу од следећег поновног покретања надаље. Ограничење слања се и даље само чува и проверава, а механизам још увек нема начин да га примени на преузимање у току. DHT и PEX испод су у истој ситуацији код обичног (неприватног) торента: сопствена подразумевана вредност ове инстанце такође још увек не досеже преузимање у току, па торент и даље сидује са обома укљученим без обзира на подешавање овде - приватни торент је сасвим други случај, погледајте напомену испод. Дугме за мапирање испод ипак ради нешто стварно: поштено тражи од рутера да проследи број порта унет горе, без обзира да ли га тренутно слуша неки торент или не.',
