  'onboarding.next': 'Даље',
  'onboarding.finish': 'Почни да користиш KnightLoader',
  'onboarding.welcome.title': 'Добро дошао у KnightLoader',
  'onboarding.welcome.body': 'KnightLoader је самостално хостован менаџер преузимања: налепи или отпусти везу, а преузима је онај позадински систем који је стварно обрађује - уграђени механизам за обичне везе ка датотекама, yt-dlp за медијске странице, debrid услугу за хостере које већ плаћаш, или JDownloader без интерфејса за све остало. Ова кратка тура обухвата једино подешавање које вреди проверити пре него што почнеш.',
  'onboarding.welcome.langLabel': 'Језик интерфејса',
  'onboarding.folder.title': 'Где би требало да заврше датотеке?',
  'onboarding.folder.body': 'Ово је фасцикла у коју се уписују завршена преузимања. Упиши путању или претражи сервер да је изабереш - можеш је поново променити било када на страници општих подешавања.',
  'onboarding.accounts.title': 'Премијум хостери, кад год пожелиш',
  'onboarding.accounts.body': 'Ред ради и потпуно без налога. Кад пожелиш пуну брзину код хостера или debrid услуге коју већ плаћаш, додај њену пријаву под Налозима - овде сада ништа не треба подешавати.',
  'onboarding.accounts.link': 'Отвори Налоге',
  'onboarding.finished.title': 'Спреман си',
  'onboarding.finished.body': 'Тиме се тура завршава. Страница Помоћ унутар Подешавања садржи потпун преглед свега осталог што ова верзија ради, а већина контрола носи сопствено објашњење иза иконице (i).',

