  'settings.downloads.diskTitle': 'Простор на диску',
  'settings.downloads.diskHint': 'Три броја која задржавају преузимања пре него што се диск напуни, а не после. Сва три значе слободне бајтове на диску на који се тренутно пише: ако је радна фасцикла на другом диску, мери се тај. Нула искључује појединачни број. Шта ово не може: не да се сваки систем питати колико је слободно, а где одговора нема, ништа се и не задржава, јер би стража која блокира кад не зна зауставила сасвим здраву машину.',
