  'settings.feeds.remembered': '{n} запамћених уноса',
  'settings.feeds.rememberedHint': 'Колико уноса ова претплата поново препознаје, да се не додају други пут док их фид још издаје. Највише 500 по претплати. Најстарији испадају први, а унос који је још у фиду никада није међу њима.',
