  'settings.headerProfiles.title': 'Профили заглавља',
  'settings.headerProfiles.hint': 'Неки сајтови дају датотеку само прегледачу који је пријављен, или само када позив стиже са неке њихове сопствене странице. Профил чува заглавља за тачно један сајт, шифрована исто као твоји подаци за пријаву, а KnightLoader их шаље уз свако преузимање са тог сајта.',
