  'detail.playPartial': 'Ово преузимање није завршено. Пустити се може само део који је већ на диску, преко тога се не може прескакати, а неке датотеке не пуштају баш ништа док последњи бајт не стигне.',
  'detail.playUnsupported': 'Овај прегледач не може да пусти ову датотеку. Отвори је или сачувај преко менија на десни клик.',
  'detail.playRemote': 'Овде се пуштају само датотеке са ове инстанце. Друга инстанца своје датотеке предаје у једном комаду и без прескакања, а с тим плејер не може да ради.',
  'detail.playNotLocal': 'Ово преузимање је дохватио JDownloader, па датотека лежи на диску тог процеса, а не на овом.',
