  'notifications.title': 'Обавештења',
  'notifications.titleHint': 'Одлучи за сваки догађај да ли се приказује као балон у апликацији, као обавештење твог оперативног система, или уопште не. Системско обавештење те стиже само док је отворена нека KnightLoader картица, а тихи режим испод важи и поред овога.',
