  'notifications.event.captchaWaiting': 'Captcha чека',
  'notifications.event.captchaWaitingHint': 'Captcha прозор се у овој картици отвара у сваком случају. Стоји на „Не приказуј ништа“ јер је тај прозор већ сам по себи порука док гледаш у њега. Постави га на системско обавештење и captcha у позадинској картици те стиже пре него што хостер одбаци сесију.',
  'notifications.event.captchaFailed': 'Captcha није успела',
  'notifications.event.captchaFailedHint': 'Нико није одговорио на време, или одговор није прошао. Преузимање иза тога остаје где јесте.',
  'notifications.event.captchaResolved': 'Captcha решена негде другде',
  'notifications.event.captchaResolvedHint': 'Неко у другом прегледачу, или аутоматски решавач, одговорио је на њу и прозор се сам затворио.',
  'notifications.systemUnavailable': 'Системска обавештења овде нису доступна: твој прегледач их нуди само преко HTTPS-а или на localhost-у. Све са ове картице се свеједно приказује у апликацији.',
  'notifications.systemBlocked': 'Твој прегледач блокира обавештења за ову адресу. Редови постављени на „Системско обавештење“ приказују се уместо тога у апликацији, док их поново не дозволиш у подешавањима сајта у свом прегледачу.',
  'notifications.systemNotGranted': 'Прегледач није дао дозволу, па овај догађај остаје у апликацији. Изабери поново „Системско обавештење“ да се питање понови.',
