  'volume.split.host': 'По хостеру',
  'volume.split.backend': 'По позадини',
  'volume.other': 'Све остало',
  'volume.empty': 'У овом периоду још ништа није завршено.',
  'volume.unsizedHint': 'Код {n} ових преузимања хостер никада није навео величину. Она збиру не додају ништа, па је стварна бројка већа од нацртане.',
  'volume.trimmedHint': 'Историја је на својој граници, па све старије од њеног најстаријег уноса недостаје и у овој кривој. Подигни горњу границу историје на овој страници ако желиш да гледаш даље уназад.',
  'volume.meter': 'Обим',
  'volume.meterHint': 'Шта је преузето откако је бројач последњи пут кренуо поново, мерено према ограничењу на страници подешавања Преузимања. Број се помера када преузимање заврши, а не док траје: он скаче, а не пузи. Сабира се из историје преузимања, па ко испразни историју, тиме и овај бројач враћа на нулу.',
