  'list.keysHint': 'Списком се управља и са тастатуре. Тастером Tab улазиш у њега, стрелицама идеш од реда до реда, размакница ред додаје у избор или га вади назад, Shift са стрелицом узима цео опсег, Enter отвара својства, а лева и десна стрелица затварају и отварају фасциклу. Сви су наведени под Подешавања, Пречице.',
  'settings.shortcuts.listTitle': 'Тастери списка',
