  'settings.eventTargets.sentCount': '{n} испоручено од покретања сервера',
  'settings.eventTargets.dropped': '{n} одбачено јер је ред био пун',
  'settings.eventTargets.droppedHint': 'Налет који стиже брже него што га ово одредиште прима одбацује се, а не чува, јер чување значи трошити меморију на поруке које су у тренутку слетања већ застареле. Ако овај број настави да расте, одредиште је преспоро за догађаје које си означио.',
  'settings.eventTargets.problem.noUrl': 'У овом реду нема адресе, па ништа не може да се пошаље. Упиши је изнад.',
  'settings.eventTargets.problem.badUrl': 'Адреса не може да се прочита као http или https адреса. Провери шему и хост.',
  'settings.eventTargets.problem.badMethod': 'Овај билд шаље GET, POST и PUT и ништа друго. Изабери једно од та три.',
  'settings.eventTargets.problem.badTemplate': 'Чувар места није затворен. Сваки се пише са по два знака процента са обе стране назива.',
  'settings.eventTargets.problem.unknownTrigger': 'Један од догађаја у овом реду није догађај који овај билд окида. Скини му ознаку и изабери неки са списка.',
  'settings.eventTargets.problem.dns': 'Хост није могао да се пронађе изнутра, из ове инстанце. Контејнер често има сопствени разрешивач имена, па адреса коју твој рачунар досеже није аутоматски и она коју досеже ова машина.',
  'settings.eventTargets.problem.refused': 'Тамо ништа не слуша. Провери порт и да ли услуга уопште ради.',
  'settings.eventTargets.problem.tls': 'Сертификат није примљен. Обично је разлог самопотписани сертификат на сопственом серверу. У сопственој мрежи узми http, или дај овом контејнеру сертификат.',
  'settings.eventTargets.problem.timeout': 'Друга страна није одговорила у оквиру временског ограничења. Подигни ограничење изнад, или шаљи на нешто брже.',
  'settings.eventTargets.problem.auth': 'Друга страна је одбила акредитиве. Провери токен у заглављима, и имај на уму да преусмерење на други хост успут одбацује заглавље Authorization.',
  'settings.eventTargets.problem.notFound': 'Друга страна нема ту путању. Код ntfy тема је део адресе, код Matrix то је ознака собе.',
  'settings.eventTargets.problem.rejected': 'Друга страна је прочитала захтев и одбила га. Одговор испод је њен сопствени текст и каже више него што би било која ознака овде могла.',
  'settings.eventTargets.problem.rateLimited': 'Друга страна тренутно одбија јер је превише стигло одједном. Скини ознаку бучнијим догађајима, или шаљи на сопствени сервер уместо на јавни.',
  'settings.eventTargets.problem.server': 'Друга страна је одговорила сопственом грешком. Понављано је онолико пута колико овај ред дозвољава, па је њен дневник следеће место које треба погледати.',
