  'settings.nav.health': 'Стање',
  'settings.module.metrics': 'Адреса мерних вредности за надзор',
  'settings.health.title': 'Стање тренутно',
  'settings.health.titleHint': 'Ова страница само чита. Ништа на њој ништа не покреће, не зауставља и не мења, а ни то што је оставиш отворену ништа не мења. Вредности се дохватају сваких десет секунди. Ако дохватање не успе, остаје да стоји последње читање, уместо да се страница испразни. Делови који морају да се испитају деле се пола минута, па оно што овде видиш може да заостаје до тридесет секунди за редовима на страници Преузимања.',
  'settings.health.version': 'Верзија',
  'settings.health.uptime': 'У раду',
  'settings.health.uptimeHint': 'Колико дуго ради овај процес, а не колико дуго ради рачунар. Контејнер који је поново покренут пре сат времена овде опет почиње од нуле, шта год домаћин говорио. Датум поред је сат самог сервера, а не сат твог прегледача.',
  'settings.health.startedAt': 'Покренуто',
  'settings.health.sampled': 'Прочитано пре {n} секунде(и)',
  'settings.health.loadFailed': 'Стање није могло да се учита. Да ли је сервер доступан?',
  'settings.health.oldHealthHint': 'Стара адреса /api/health се није променила и одговара „ok“ докле год овај процес ради, шта год на овој страници писало. То је намерно: читају је провера здравља самог контејнера, мост Click\'n\'Load и претрага инстанци у твојој мрежи из мобилне апликације, а другачији одговор од „ok“ означио би контејнер као нездрав и телефон би престао да налази ову инстанцу. Грешка се јавља на овој страници. Она адреса само каже да ли ико слуша.',
  'health.state.ok': 'Ради',
  'health.state.degraded': 'Ради, али са грешком',
  'health.state.failed': 'Не ради',
  'health.state.unused': 'Овде није у употреби',
  'health.state.unknown': 'Овде се не може проверити',
  'settings.health.parts': 'Делови',
  'settings.health.partsHint': 'По један ред за сваки део апликације који може да падне сам за себе. Део који на овој инстанци никада ниси подесио то и каже, уместо да се рачуна као грешка, а део који овај билд не може да пита каже исто. То је трећи одговор, а не тиха нула. Читање реда ништа не мења: део који каже да не ради већ неко време пада, а ти то тек овде видиш.',
  'health.part.store': 'База података',
  'health.part.queue': 'Ред чекања',
