  'health.part.jd': 'Пратећи JDownloader',
  'health.part.ytdlp': 'yt-dlp',
  'health.part.accounts': 'Хостер налози',
  'health.part.feeds': 'Претплате на фидове',
  'health.part.relay': 'Релеј',
  'health.part.captcha': 'Captcha',
  'health.remedy.store.failed': 'База података није одговорила. Преузимања настављају да раде, али о њима се више ништа не бележи, па би поновно покретање изгубило све што се од тада променило. Провери да ли је фасцикла са подацима још монтирана и да ли се у њу још може писати.',
  'health.remedy.jd.unreachable': 'KL_JD наводи адресу коју ова инстанца тренутно не досеже. Провери да ли контејнер JDownloader ради и да ли његов API порт одговара одавде. Везе које може да дохвати само JDownloader у међувремену остају у реду и нису пропале.',
  'health.remedy.jd.notWired': 'JDownloader опет одговара, али је овај процес своје позадине повезао при покретању и тада га није имао. Поново покрени KnightLoader да га узме у рад.',
  'health.remedy.ytdlp.missing': 'При покретању овог процеса није нађен ниједан yt-dlp (KL_YTDLP или „yt-dlp“ у PATH). Медијске странице тада падају са сопственом грешком сајта, уместо да се рашире у варијанте. Да би био нађен, потребно је поновно покретање.',
  'health.remedy.disk.low': 'Циљна фасцикла је испод границе коју си поставио на страници Преузимања. Тамо не почиње ништа ново док опет не буде места, или док не спустиш границу. Оно што већ ради, та граница не зауставља.',
  'health.remedy.disk.elsewhere': 'Једне фасцикле нема, зато бројеви описују најближу фасциклу изнад ње. Ако се нека монтажа није подигла, то је сасвим други диск. Погледај путању пре него што поверујеш бројевима.',
  'health.remedy.accounts.benched': 'Бар један хостер налог се после грешке оставља на миру. Сам се покушава још једном када чекање прође, а чекање се сваки пут удвостручује. Отвори Налоге и на том реду притисни Освежи ако хоћеш да знаш сада.',
  'health.remedy.accounts.invalid': 'Бар један хостер налог је одбијен. Помаже нов кључ или обновљена претплата, чекање не.',
  'health.remedy.feeds.failing': 'Код бар једне претплате последње дохватање није успело. Која и зашто, стоји на страници Преузимања поред фида и у редовима дневника на страници Дијагностика.',
  'health.remedy.relay.down': 'Адреса релеја је сачувана, а веза не стоји. Ова инстанца сама даље покушава и локално све ради као иначе. Само споља тренутно није доступна.',
  'health.remedy.captcha.waiting': 'Позадина је стала и пита човека. Иза тога се ништа не креће док неко не одговори.',
  'settings.health.tasks': 'Преузимања тренутно',
  'settings.health.tasksHint': 'Тренутни снимак списка, а не зборник кроз време. „Неуспело“ броји редове који управо стоје на списку са грешком на себи, па број пада када их почистиш и када се списак уреди после дана које си подесио, а расте опет када нешто ново крене наопако. Ништа овде није стопа, и ништа овде не говори колико је пута нешто пропало.',
