  'settings.health.nothingFailed': 'На списку ништа није пропало.',
  'settings.health.diskLink': 'Колико места има на циљним фасциклама, стоји на страници Преузимања',
  'settings.health.scrape': 'Надзор',
  'settings.health.scrapeSwitch': 'Одговарај на адреси мерних вредности',
  'settings.health.scrapeHint': 'Отвара другу адресу која те исте вредности даје као обичан текст, у формату који читају Prometheus и по њему грађена оруђа. Она се дохвата, никада се не шаље: ништа не напушта ову машину док твој сопствени надзор не дође овамо и не затражи то. Док је ово искључено, та адреса уопште не постоји и одговара са 404, исто као и свака адреса коју ова апликација нема. На инстанци са лозинком дохватање тражи један од твојих API токена, а сваком сакупљачу се може рећи да га шаље. Сакупљач не шаље заглавље порекла и зато прође. Картица прегледача на другој адреси га шаље и бива одбијена ако се не поклапа са адресом ове инстанце. У тексту стоје путање твојих циљних фасцикли, па га дај само онамо где би дао и саме називе фасцикли.',
