  'settings.health.scrapeOffHint': 'Ова адреса не одговара ништа док је прекидач изнад искључен.',
  'settings.diagnostics.systemTitle': 'Системске информације',
  'settings.diagnostics.fileTitle': 'Датотека дневника',
  'settings.diagnostics.fileOn': 'Уписуј дневник у датотеку',
  'settings.diagnostics.fileOnHint': 'Стоји искључено док га не укључиш, а ажурирање га никада не укључује за тебе. Укључено, ова инстанца сваки ред који забележи уписује у датотеку у својој фасцикли са подацима, да пад од прекјуче и после поновног покретања још буде читљив. Ред дневника може да наведе адресу фида на који си претплаћен, зато ту датотеку сматрај својом. У контејнеру исти ти редови већ стижу у docker logs. Датотека је оно што остане када то прође.',
