  'detail.log.empty': 'За ово преузимање ништа није забележено.',
  'detail.log.emptyHint': 'Не бележи сваки ред којем преузимању припада. Преузимање може да упадне у невоље, а да се овде не појави ни један једини ред. Цео дневник стоји на страници Дијагностика.',
  'detail.log.openDiagnostics': 'Отвори цео дневник',
  'detail.log.remote': 'Дневник остаје на инстанци која га је написала. За преузимање које ради на другој машини овде зато нема шта да се прикаже.',
  'settings.owner.identityTitle': 'Као ко ова инстанца пише',
  'settings.owner.identityHint': 'Свака датотека коју ова инстанца направи добија овог власника и ова права, а исто важи и за све што она покреће: yt-dlp, ffmpeg и приложени JDownloader. У контејнеру је идентитет одређен у тренутку када контејнер стартује, налогом под којим је покренут, и са ове странице се на томе не може ништа изменити.',
  'settings.owner.uid': 'Корисник',
  'settings.owner.gid': 'Група',
  'settings.owner.umask': 'Umask',
  'settings.owner.umaskUnknown': 'Овај кернел је не пријављује',
  'settings.owner.asked': 'Затражено',
  'settings.owner.envIgnored': '{name}={value} је постављено, али ту променљиву у овој слици нико не чита. Идентитет одређује налог под којим је контејнер покренут, а то је {owner}.',
  'settings.owner.envHow': 'Ако хоћеш да ради под другим налогом, наведи га у наредби за покретање: --user <uid>:<gid>. На Unraid-у то иде у Extra Parameters, а контејнер мора да се направи поново да би то ступило на снагу.',
  'settings.owner.desktopNote': 'Десктоп апликација ради под твојим сопственим налогом. PUID, PGID и UMASK су подешавања контејнера и овде не раде ништа.',
  'settings.owner.noOwners': 'На овом систему датотеке немају власнике, па нема шта да се упоређује. То није грешка.',
  'settings.owner.checkTitle': 'Провера фасцикли',
  'settings.owner.checkHint': 'Ово заиста упише по једну датотеку и по једну подфасциклу у сваку фасциклу, потом погледа чије су и ко још сме да их чита, и оба уклони. То мора да се измери, а не сме да се израчуна: дељена фасцикла може да носи сопствена правила права, а фасцикла са постављеним set-group-id дели другу групу од оне коју овај процес има. Провера иде сама од себе када сачуваш промењену фасциклу, и сваки пут када притиснеш дугме.',
  'settings.owner.run': 'Провери фасцикле сада',
  'settings.owner.running': 'Провера у току…',
  'settings.owner.never': 'Још није проверено.',
  'settings.owner.checkedAt': 'Последњи пут проверено {time}.',
  'settings.owner.checkFailed': 'Провера није успела да се изврши: {error}',
  'settings.owner.role.downloads': 'Фасцикла за преузимања',
  'settings.owner.role.work': 'Радна фасцикла',
  'settings.owner.role.category': 'Фасцикла категорије',
  'settings.owner.role.watch': 'Надгледана фасцикла',
  'settings.owner.v.ok': 'Датотеке овде слећу као {fileOwner} са {fileMode}, нове подфасцикле са {subdirMode}, а сама фасцикла припада {dirOwner}. На томе ништа не упада у очи.',
  'settings.owner.v.ownerMismatch': 'Датотеке овде слећу као {fileOwner}, а фасцикла припада {dirOwner}. Читање обично још иде, преименовање, премештање и брисање са другог налога не, а све што очекује да фасцикла поседује свој садржај те датотеке сматра страним.',
  'settings.owner.v.groupUnreadable': 'Датотеке овде слећу са {fileMode}, па их отворити може само {fileOwner}. Оно што ради под другим налогом види називе и ништа више.',
  'settings.owner.v.dirUnreadable': 'Нове подфасцикле овде слећу са {subdirMode}. У њих осим {fileOwner} нико не улази, шта год датотеке у њима дозвољавале, а свако преузимање слеће у једну такву.',
  'settings.owner.v.notWritable': 'Ова инстанца овде уопште не може да пише: {detail}',
  'settings.owner.v.missing': 'Фасцикле нема. Направиће се када се у њу први пут нешто упише.',
  'settings.owner.v.unknown': 'На овом систему датотеке немају власнике, па овде нема шта да се упоређује. То није грешка.',
  'settings.owner.fix.user': 'Покрени контејнер под налогом којем фасцикла припада: --user {dirUid}:{dirGid} у наредби за покретање. На Unraid-у то иде у Extra Parameters.',
  'settings.owner.fix.chown': 'Или фасциклу предај, на домаћину: chown -R {uid}:{gid} {dir}',
  'settings.owner.fix.mask': 'На томе ова инстанца не може ништа. Маска долази од онога што је покренуло контејнер, а монтирана дељена фасцикла може опцијом umask, file_mode или dir_mode да наметне своју. Исправи то тамо где је фасцикла монтирана.',
  'settings.owner.fix.recreate': 'Промењена наредба за покретање захтева поново направљен контејнер. Поновно покретање није довољно: идентитет је одређен у тренутку када стартује.',
  'settings.owner.fix.past': 'Већ преузете датотеке задржавају власника са којим су записане. Оно што промениш важи за све што следи, за остало ти треба наредба изнад.',
  'settings.selftest.title': 'Самопровера',
  'settings.selftest.hint': 'Све што ова инстанца може да сазна о себи: пратећи JDownloader, yt-dlp, твоје фасцикле, твоје debrid пријаве, релеј и сат. Све то ради на овом рачунару. Једино што га напушта су debrid пријаве, које иду ка добављачима које си подесио.',
