  'settings.selftest.jd.provisioningOff': 'Постављање је искључено и није задата адреса, па нема пратиоца који би се досегао.',
  'settings.selftest.jd.missing': 'Нема адресе пратиоца. Шифровани DLC и контејнерске везе се одбијају.',
  'settings.selftest.jd.missingAdvice': 'Овај билд при подизању обично сам покрене свој JDownloader без прозора и сам упише KL_JD. То што је празно значи да то покретање није успело. Потражи „JD provisioning failed“ у дневнику ниже, или постави KL_JD на сопствени JDownloader.',
  'settings.selftest.jd.unreachable': '{address} није одговорила.',
  'settings.selftest.jd.unreachableAdvice': 'Адреса је сачувана, а на њој ништа не слуша. Провери да ли пратилац ради и да ли је његов порт 3128 доступан изнутра, из овог контејнера, а не само са домаћина.',
  'settings.selftest.jd.noVersion': 'Одговара, али не каже која је ревизија.',
