  'settings.selftest.folders.missing': '{dir} још не постоји, зато бројеви описују {measured}.',
  'settings.selftest.folders.missingAdvice': 'То је нормално за фасциклу у коју још ништа није уписано, и прво преузимање је прави. Али ако је {measured} корен носача, недостаје монтажа коју си очекивао, и преузимање слеће у контејнер, а не на твој диск.',
  'settings.selftest.folders.low': 'На {dir} је остало само {free}, испод границе {mark} на којој ред стаје.',
  'settings.selftest.folders.noMark': 'На {dir} је слободно {free}. Ниси поставио фиксан праг, па ред задржава преузимање само када оно овако већ не би стало.',
  'settings.selftest.folders.unknown': 'Ова платформа се не може питати колико места има на {dir}.',
